// 이미지(derefUri) 없을 때 대체 이미지 (밤 하늘 별똥별 이미지)
String base64 =
    "data:image/png;base64,";

// 웹서버로부터 모든 CAP(xml) 가져오기
Future<List<Post>> fetchPost() async {
  //final response = await http.get('https://jsonplaceholder.typicode.com/posts');
  final response = await http.get('http://localhost:3000/flutterTest');

  // 200(성공): 서버가 요청을 제대로 처리했다는 뜻이다. 이는 주로 서버가 요청한 페이지를 제공했다는 의미로 쓰인다.
  if (response.statusCode == 200) {
    List list = jsonDecode(response.body);
    var postList = list.map((element) => Post.fromJson(element)).toList();
    return postList;
  } else {
    throw Exception('Failed to load post');
  }
}

// 웹서버로부터 가져온 데이터의 형식
class Post {
  //final int userId;
  //final int id;
  final String fileName; // xml 파일의 이름
  final String xmlData; // 실제 xml 데이터

  Post({/*this.userId, this.id, */ this.fileName, this.xmlData});

  factory Post.fromJson(Map<String, dynamic> json) {
    return Post(
      //userId: json['userId'],
      //id: json['id'],
      //title: json['title'],
      //body: json['body'],
      fileName: json['fileName'],
      xmlData: json['data'],
    );
  }
}

// 주요 데이터를 parsing하는 함수
// headline, description, sent를 parsing
Map xmlParsing(String xml) {
  Map data = new Map();

  //print(xml);
  final document = XmlDocument.parse(xml);
  //final titles = document.findAllElements('headline');
  //titles.map((node) => node.text).forEach(print);

  // headline
  XmlElement node =
      document.getElement('alert').getElement('info').getElement('headline');
  if (node == null)
    data['headline'] = '제목 없음';
  else
    data['headline'] = node.text;

  // description
  node =
      document.getElement('alert').getElement('info').getElement('description');
  if (node == null)
    data['description'] = '설명 없음';
  else
    data['description'] = node.text;

  // sent
  data['sent'] = document.getElement('alert').getElement('sent').text;

  return data;
}

// 서브 데이터를 parsing하는 함수
// derefUri, areaDesc를 parsing
Map xmlParsing2(String xml) {
  Map data = new Map();

  final document = XmlDocument.parse(xml);

  // derefUri (Dereferenced URI)
  XmlElement node =
      document.getElement('alert').getElement('info').getElement('resource');
  if (node != null) {
    if (node.getElement('derefUri') != null)
      data['derefUri'] = node.getElement('derefUri').text;
    else
      data['derefUri'] = base64;
  } else
    data['derefUri'] = base64;
  //print(data['derefUri']);

  // areaDesc
  data['areaDesc'] = document
      .getElement('alert')
      .getElement('info')
      .getElement('area')
      .getElement('areaDesc')
      .text;

  return data;
}

void main() => runApp(MyApp());

// 초기 화면
class MyApp extends StatefulWidget {
  MyApp({Key key}) : super(key: key);

  @override
  _MyAppState createState() => _MyAppState();
}

// 초기 화면의 state
class _MyAppState extends State<MyApp> {
  Future<List<Post>> postList;

  @override
  void initState() {
    super.initState();
    postList = fetchPost();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'jvvp',
      // 상단 컬러 지정
      theme: ThemeData(
        primarySwatch: Colors.amber,
      ),
      home: Scaffold(
        appBar: AppBar(
          title: Text('CAP Messages'),
        ),
        body: Center(
          child: FutureBuilder<List<Post>>(
            future: postList,
            builder: (context, snapshot) {
              if (snapshot.hasData) {
                return ListView.builder(
                  itemCount: snapshot.data.length,
                  itemBuilder: (context, index) {
                    Post post = snapshot.data[index];
                    Map data =
                        xmlParsing(post.xmlData); // 웹서버에서 받은 xml 데이터를 parsing
                    return Card(
                        child: ListTile(
                      //title: Text(post.title),
                      //subtitle: Text(post.body),
                      title: Text(data['headline']),
                      subtitle: Text(data['description'] +
                          '\n' +
                          data['sent'].replaceAll('T', ' ')),
                      // list 중 하나를 클릭했을 때, 해당 CAP의 세부사항 화면으로 라우팅함
                      onTap: () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (context) => CAPDetailPage(
                              mainData: data,
                              subData: xmlParsing2(post.xmlData),
                            ),
                          ),
                        );
                      },
                    ));
                  },
                );
              } else if (snapshot.hasError) {
                return Text("${snapshot.error}");
              }

              return CircularProgressIndicator();
            },
          ),
        ),
      ),
    );
  }
}

